// Package businessmcp is the tool layer of Django's run_mcp_server
// (application/mcp_server/server.py create_mcp_server): the declared tools,
// the SDK's jsonschema input validation and call_tool's dispatch.
package businessmcp

import (
	_ "embed"
	"encoding/json"
	"errors"
	"math"
	"strconv"
	"strings"

	"github.com/carbogninalberto/assozeta/BE_GO/internal/domain"
	"github.com/carbogninalberto/assozeta/BE_GO/internal/dto"
)

// tools.json is TOOL_DEFINITIONS (business and manual tools) as the MCP SDK
// lists them, generated by TESTS/fixtures/generate_mcp_server_models.py.
//
//go:embed tools.json
var toolsJSON []byte

// Declaration is one tools/list entry with its exact schema JSON.
type Declaration struct {
	Name        string          `json:"name"`
	Description string          `json:"description"`
	InputSchema json.RawMessage `json:"inputSchema"`
	schema      any
}

var declarations = func() []Declaration {
	var items []Declaration
	if err := json.Unmarshal(toolsJSON, &items); err != nil {
		panic("business MCP tools: " + err.Error())
	}
	for i := range items {
		schema, err := pythonLoads(items[i].InputSchema)
		if err != nil {
			panic("business MCP schema: " + err.Error())
		}
		items[i].schema = schema
	}
	return items
}()

// Declarations are the tools in TOOL_DEFINITIONS order.
func Declarations() []Declaration { return append([]Declaration(nil), declarations...) }

func declaration(name string) (Declaration, bool) {
	for _, item := range declarations {
		if item.Name == name {
			return item, true
		}
	}
	return Declaration{}, false
}

// pythonLoads is json.loads: objects keep the first position of a repeated
// key with its last value.
func pythonLoads(raw []byte) (any, error) {
	value, err := dto.ParseReferenceJSON(raw)
	if err != nil {
		return nil, err
	}
	return pythonDicts(value), nil
}

func pythonDicts(value any) any {
	switch typed := value.(type) {
	case domain.RequestObject:
		object := dto.PythonDict(typed)
		for i := range object {
			object[i].Value = pythonDicts(object[i].Value)
		}
		return object
	case []any:
		for i := range typed {
			typed[i] = pythonDicts(typed[i])
		}
	}
	return value
}

// errUnorderable is a best_match path comparison Python cannot make.
var errUnorderable = errors.New("unorderable jsonschema error paths")

type schemaError struct {
	path     []any // string property names and int indexes
	message  string
	schema   domain.RequestObject
	instance any
}

// isType is the draft 2020-12 type checker.
func isType(instance any, name string) bool {
	switch name {
	case "object":
		_, ok := instance.(domain.RequestObject)
		return ok
	case "array":
		_, ok := instance.([]any)
		return ok
	case "string":
		_, ok := instance.(string)
		return ok
	case "boolean":
		_, ok := instance.(bool)
		return ok
	case "null":
		return instance == nil
	case "integer", "number":
		number, ok := instance.(json.Number)
		if !ok {
			return false
		}
		if name == "number" || !strings.ContainsAny(string(number), ".eE") {
			return true
		}
		value, err := strconv.ParseFloat(string(number), 64)
		return err == nil && !math.IsInf(value, 0) && value == math.Trunc(value)
	}
	return false
}

func extend(path []any, item any) []any {
	return append(append([]any(nil), path...), item)
}

// iterErrors is Validator.iter_errors for the keywords the declared
// schemas use (type, properties, required, items, enum).
func iterErrors(instance any, schema domain.RequestObject, path []any) []schemaError {
	var found []schemaError
	for _, keyword := range schema {
		switch keyword.Name {
		case "type":
			name, _ := keyword.Value.(string)
			if !isType(instance, name) {
				found = append(found, schemaError{path: path, schema: schema, instance: instance,
					message: dto.PythonRepr(instance) + " is not of type " + dto.PythonRepr(name)})
			}
		case "properties":
			object, ok := instance.(domain.RequestObject)
			if !ok {
				continue
			}
			for _, property := range keyword.Value.(domain.RequestObject) {
				if value, present := object.Lookup(property.Name); present {
					found = append(found, iterErrors(value, property.Value.(domain.RequestObject), extend(path, property.Name))...)
				}
			}
		case "required":
			object, ok := instance.(domain.RequestObject)
			if !ok {
				continue
			}
			for _, property := range keyword.Value.([]any) {
				name := property.(string)
				if _, present := object.Lookup(name); !present {
					found = append(found, schemaError{path: path, schema: schema, instance: instance,
						message: dto.PythonRepr(name) + " is a required property"})
				}
			}
		case "items":
			items, ok := instance.([]any)
			if !ok {
				continue
			}
			for index, item := range items {
				found = append(found, iterErrors(item, keyword.Value.(domain.RequestObject), extend(path, index))...)
			}
		case "enum":
			text, isText := instance.(string)
			matched := false
			for _, option := range keyword.Value.([]any) {
				if isText && option == text {
					matched = true
				}
			}
			if !matched {
				found = append(found, schemaError{path: path, schema: schema, instance: instance,
					message: dto.PythonRepr(instance) + " is not one of " + dto.PythonRepr(keyword.Value)})
			}
		}
	}
	return found
}

// matchesType is ValidationError._matches_type.
func (e schemaError) matchesType() bool {
	expected, present := e.schema.Lookup("type")
	name, ok := expected.(string)
	return present && ok && isType(e.instance, name)
}

// comparePaths compares two error paths like Python deques.
func comparePaths(left, right []any) (int, error) {
	for i := 0; i < len(left) && i < len(right); i++ {
		switch a := left[i].(type) {
		case string:
			b, ok := right[i].(string)
			if !ok {
				return 0, errUnorderable
			}
			if a != b {
				return strings.Compare(a, b), nil
			}
		case int:
			b, ok := right[i].(int)
			if !ok {
				return 0, errUnorderable
			}
			if a != b {
				if a < b {
					return -1, nil
				}
				return 1, nil
			}
		}
	}
	return len(left) - len(right), nil
}

// relevanceLess reports relevance(a) < relevance(b) (by_relevance's key:
// -len(path), path, then errors whose instance does not match the type).
func relevanceLess(a, b schemaError) (bool, error) {
	if len(a.path) != len(b.path) {
		return len(a.path) > len(b.path), nil
	}
	order, err := comparePaths(a.path, b.path)
	if err != nil || order != 0 {
		return order < 0, err
	}
	return a.matchesType() && !b.matchesType(), nil
}

// ValidateArguments is jsonschema.validate(arguments, tool.inputSchema) with
// best_match; it returns the SDK's error text ("" when valid).
func ValidateArguments(name string, raw json.RawMessage) (string, error) {
	tool, ok := declaration(name)
	if !ok {
		return "", nil
	}
	instance := any(domain.RequestObject{})
	if len(raw) > 0 && string(raw) != "null" {
		parsed, err := pythonLoads(raw)
		if err != nil {
			return "", err
		}
		instance = parsed
	}
	found := iterErrors(instance, tool.schema.(domain.RequestObject), nil)
	if len(found) == 0 {
		return "", nil
	}
	best := found[0]
	for _, candidate := range found[1:] {
		less, err := relevanceLess(best, candidate)
		if err != nil {
			return "", err
		}
		if less {
			best = candidate
		}
	}
	return "Input validation error: " + best.message, nil
}
